package backend

type Item struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type Page struct {
	Items      []Item `json:"items"`
	NextCursor *string `json:"next_cursor"`
}

var pageTwoCursor = "cursor-2"

func FetchItems(cursor *string, limit int) Page {
	if limit < 1 {
		return Page{Items: []Item{}, NextCursor: nil}
	}

	items := []Item{
		{ID: "i1", Name: "one"},
		{ID: "i2", Name: "two"},
		{ID: "i3", Name: "three"},
	}

	start := 0
	if cursor != nil {
		if *cursor != pageTwoCursor {
			return Page{Items: []Item{}, NextCursor: nil}
		}
		start = 2
	}

	end := start + limit
	if end > len(items) {
		end = len(items)
	}

	page := Page{Items: items[start:end], NextCursor: nil}
	if end < len(items) {
		next := pageTwoCursor
		page.NextCursor = &next
	}
	return page
}

func FetchAllItems(limit int) []Item {
	if limit < 1 {
		return []Item{}
	}

	all := []Item{}
	var cursor *string
	for {
		page := FetchItems(cursor, limit)
		all = append(all, page.Items...)
		if page.NextCursor == nil {
			return all
		}
		cursor = page.NextCursor
	}
}

